/// <summary>
/// CB521_ExciseRegister
/// Service class for excise information update table
/// </summary>
class METExciseInformationTableUpdateService extends SysOperationServiceBase
{
    METDutyRollVariance             dutyRollVariance;
    METDutyCreditTable              dutyCreditTable;
    METExciseInformationTable       metExciseInformationTable;

    Map                             itemCache;
    Map                             inventDimSiteCache;

}

Method.Source:
    /// <summary>
    /// Item cache for reread
    /// </summary>
    /// <param name = "_itemId">item</param>
    /// <returns>container</returns>
    public container getItemCache(ItemId   _itemId)
    {
        container   value;

        if (!itemCache)
        {
            itemCache = new Map(Types::String, Types::Container);
        }

        if (itemCache.exists(_itemId))
        {
            value =  itemCache.lookup(_itemId);
        }
        else
        {
            value = [InventTable::find(_itemId), METInventTable::find(_itemId)];
            itemCache.insert(_itemId, value);
        }

        return value;
    }

    /// <summary>
    /// SiteId from Dim id
    /// </summary>
    /// <param name = "_inventDimId">inventDimid</param>
    /// <returns>inventSiteId</returns>
    public InventSiteId getInventSiteFromInventDimId(InventDimId  _inventDimId)
    {
        InventSiteId  inventSiteId;

        if (!inventDimSiteCache)
        {
            inventDimSiteCache = new Map(Types::String, Types::String);
        }

        if (inventDimSiteCache.exists(_inventDimId))
        {
            inventSiteId = inventDimSiteCache.lookup(_inventDimId);
        }
        else
        {
            inventSiteId = InventDim::find(_inventDimId).InventSiteId;
            inventDimSiteCache.insert(_inventDimId, inventSiteId);
        }

        return inventSiteId;
    }

    /// <summary>
    /// Process method to initiate service class
    /// </summary>
    /// <param name = "_contract">Contract class</param>
    public void process(METExciseInformationTableUpdateContract     _contract)
    {
        BatchHeader                                 batchHeader;
        SysOperationServiceController               runTaskController;
        METExciseRegisterOriginTypes                metExciseRegisterOriginTypes;
        METExciseInformationTableUpdateContract     contract;

        while select ReferenceId, TransactionType, CreateDutyCredit from metExciseRegisterOriginTypes
            where metExciseRegisterOriginTypes.UpdateRegister == NoYes::Yes
        {
            if (this.isExecutingInBatch())
            {
                runTaskController = new SysOperationServiceController(classStr(METExciseInformationTableUpdateService), methodStr(METExciseInformationTableUpdateService, runExciseInformationTableUpdate));
            
                contract = runTaskController.getDataContractObject('_contract');

                if (!batchHeader)
                {
                    batchHeader = this.getCurrentBatchHeader();
                }

                contract.parmReferenceId(metExciseRegisterOriginTypes.ReferenceId);
                contract.parmTransactionType(metExciseRegisterOriginTypes.TransactionType);
                contract.parmCreateDutyCredit(metExciseRegisterOriginTypes.CreateDutyCredit);

                batchHeader.addRuntimeTask(runTaskController, this.getCurrentBatchTask().RecId);
            }
            else
            {
                contract = new METExciseInformationTableUpdateContract();

                contract.parmReferenceId(metExciseRegisterOriginTypes.ReferenceId);
                contract.parmTransactionType(metExciseRegisterOriginTypes.TransactionType);
                contract.parmCreateDutyCredit(metExciseRegisterOriginTypes.CreateDutyCredit);

                this.runExciseInformationTableUpdate(contract);
            }
        }

        if (batchHeader)
        {
            batchHeader.save();
        }
    }

    /// <summary>
    /// Run process method
    /// </summary>
    /// <param name = "_contract">Contract class reference</param>
    public void runExciseInformationTableUpdate(METExciseInformationTableUpdateContract     _contract)
    {
        METInventTransExciseRegisterUpdateView          metInventTransExciseRegisterUpdateView, metInventTransExciseViewFilter;
        boolean                                         validInsert;
        boolean                                         isReturn;
        boolean                                         validPreInsert, onlyCredit;
        METExciseRegisterEntry                          metExciseRegisterEntry;
        TransDateTime                                   transDateTime = DateTimeUtil::utcNow();
        METExciseInformationTable                       mETExciseInformationTablePOReturnUpdate; 
        METCustParameters                               metCustParameters = METCustParameters::Find();

        // Process excise register entries together with related inventory transactions for specific category PO/TO to build the records into excise information table with business rules.
        while select validtimestate(transDateTime) metExciseRegisterEntry
            exists join metInventTransExciseViewFilter
                where metInventTransExciseViewFilter.ItemId == metExciseRegisterEntry.ItemId
                && metInventTransExciseViewFilter.ReferenceId == metExciseRegisterEntry.OrderNumber
                && (metInventTransExciseViewFilter.ReferenceCategory == InventTransType::Purch
                    || metInventTransExciseViewFilter.ReferenceCategory == InventTransType::TransferOrderReceive)
                && metInventTransExciseViewFilter.ReferenceCategory == _contract.parmReferenceId()
                && metExciseRegisterEntry.Migrated == NoYes::No
                && metExciseRegisterEntry.IsError == NoYes::No
            notexists join metExciseInformationTable
                where metExciseInformationTable.ExciseRegisterReferenceId == metExciseRegisterEntry.ReferenceId
        {
            if (_contract.parmTransactionType() == METTransactionType::Positive && metExciseRegisterEntry.ReceiptQuantity > 0)
            {
                // This is to check whether the inventtrans record already exists in excise information table for the same item and order number.
                // Scenario where PO has multiple lines for same item and same order number.

                select firstonly ReferenceId, ReferenceCategory, InventTransRecId, ItemId, inventDimId, InventTransId, StatusReceipt from metInventTransExciseRegisterUpdateView
                    where metInventTransExciseRegisterUpdateView.ItemId == metExciseRegisterEntry.ItemId &&
                        metInventTransExciseRegisterUpdateView.ReferenceId == metExciseRegisterEntry.OrderNumber &&
                    metInventTransExciseRegisterUpdateView.ReferenceCategory == _contract.parmReferenceId() &&
                    ((metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::Purch && (metInventTransExciseRegisterUpdateView.StatusReceipt == StatusReceipt::Received || metInventTransExciseRegisterUpdateView.StatusReceipt == StatusReceipt::Purchased)) ||
                     (metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::TransferOrderReceive && metInventTransExciseRegisterUpdateView.StatusReceipt == StatusReceipt::Purchased))
                    notexists join metExciseInformationTable
                        where metInventTransExciseRegisterUpdateView.InventTransRecId == metExciseInformationTable.InventTransRefRecId &&
                                metExciseInformationTable.Lodgement == metExciseRegisterEntry.Lodgement;

                // continue to next if no inventtrans record found for the excise register entry.
                if (!metInventTransExciseRegisterUpdateView.RecId)
                {
                    this.flagErrorInRegisterEntry(metExciseRegisterEntry);
                    continue;
                }

                metExciseInformationTable.clear();
                metExciseInformationTable.ReferenceNumber                   = metInventTransExciseRegisterUpdateView.ReferenceId;
                metExciseInformationTable.InventTransType                   = metInventTransExciseRegisterUpdateView.ReferenceCategory;
                metExciseInformationTable.InventTransRefRecId               = metInventTransExciseRegisterUpdateView.InventTransRecId;
                metExciseInformationTable.ItemId                            = metInventTransExciseRegisterUpdateView.ItemId;
                metExciseInformationTable.SiteId                            = this.getInventSiteFromInventDimId(metInventTransExciseRegisterUpdateView.inventDimId);
                metExciseInformationTable.InventTransId                     = metInventTransExciseRegisterUpdateView.InventTransId;
                metExciseInformationTable.ExciseRegisterReferenceId         = metExciseRegisterEntry.ReferenceId;
                metExciseInformationTable.VersionNumberRegister                     = metExciseRegisterEntry.VersionNumberRegister;
                
                switch (metInventTransExciseRegisterUpdateView.ReferenceCategory)
                {
                    case InventTransType::Purch:
                        StatusReceipt purchStatus = metInventTransExciseRegisterUpdateView.StatusReceipt;
 
                        if (purchStatus == StatusReceipt::Received ||  purchStatus == StatusReceipt::Purchased)
                        {
                            //<Task 278335: CB521 - Excise Register - Undertake Build - Part 9 (SG) - Account for receiving adjustments on the register>
                            if (metExciseInformationTable.InventoryQty < 0)
                            {
                                select firstonly forupdate mETExciseInformationTablePOReturnUpdate order by RecId desc
                                    where mETExciseInformationTablePOReturnUpdate.ItemId == metExciseInformationTable.ItemId
                                    && mETExciseInformationTablePOReturnUpdate.SiteId == metExciseInformationTable.SiteId
                                    && mETExciseInformationTablePOReturnUpdate.LodgementClosed == NoYes::No
                                    && mETExciseInformationTablePOReturnUpdate.InventoryQty > 0;

                                if (mETExciseInformationTablePOReturnUpdate.RecId)
                                {
                                    mETExciseInformationTablePOReturnUpdate.InventoryQty = mETExciseInformationTablePOReturnUpdate.InventoryQty +  metExciseInformationTable.InventoryQty;
                                        
                                    ttsbegin;
                                    if (mETExciseInformationTablePOReturnUpdate.validateWrite())
                                    {
                                        mETExciseInformationTablePOReturnUpdate.update();
                                    }
                                    ttscommit;
                                }
                            }
                            //</Task 278335: CB521 - Excise Register - Undertake Build - Part 9 (SG) - Account for receiving adjustments on the register>

                            validInsert = this.mapTransferOrderShipAndReceiveData(metExciseInformationTable, metExciseRegisterEntry, metInventTransExciseRegisterUpdateView);
                        }
                        break;

                    case InventTransType::TransferOrderReceive:
                        if (metInventTransExciseRegisterUpdateView.StatusReceipt == StatusReceipt::Purchased)
                        {
                            validInsert = this.mapTransferOrderShipAndReceiveData(metExciseInformationTable, metExciseRegisterEntry, metInventTransExciseRegisterUpdateView);
                        }
                        break;

                    default :
                        break;
                }
                validInsert = this.addingExciseInformationRecordToRecordList(metExciseInformationTable, validInsert, metExciseRegisterEntry);
            }
        }

        while select metInventTransExciseRegisterUpdateView
     where metInventTransExciseRegisterUpdateView.ReferenceCategory == _contract.parmReferenceId()
         notexists join metExciseInformationTable
             where metInventTransExciseRegisterUpdateView.InventTransRecId == metExciseInformationTable.InventTransRefRecId
        {
            validInsert = false;
            onlyCredit = false;
     
            if ((_contract.parmTransactionType() == METTransactionType::Positive && metInventTransExciseRegisterUpdateView.Qty > 0) ||
                (_contract.parmTransactionType() == METTransactionType::Negative && metInventTransExciseRegisterUpdateView.Qty < 0))
            {
                metExciseInformationTable.clear();
                metExciseInformationTable.ReferenceNumber       = metInventTransExciseRegisterUpdateView.ReferenceId;
                metExciseInformationTable.InventTransType       = metInventTransExciseRegisterUpdateView.ReferenceCategory;
                metExciseInformationTable.InventTransRefRecId   = metInventTransExciseRegisterUpdateView.InventTransRecId;
                metExciseInformationTable.ItemId                = metInventTransExciseRegisterUpdateView.ItemId;
                metExciseInformationTable.SiteId                = this.getInventSiteFromInventDimId(metInventTransExciseRegisterUpdateView.inventDimId);
                metExciseInformationTable.InventTransId         = metInventTransExciseRegisterUpdateView.InventTransId;
       
                if (metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::Sales &&
             (metInventTransExciseRegisterUpdateView.StatusIssue == StatusIssue::Sold || metInventTransExciseRegisterUpdateView.StatusIssue == StatusIssue::Deducted ||
             metInventTransExciseRegisterUpdateView.StatusReceipt == StatusReceipt::Received ||  metInventTransExciseRegisterUpdateView.StatusReceipt == StatusReceipt::Purchased))
                {
                    metExciseInformationTable.InventoryQty  = metInventTransExciseRegisterUpdateView.Qty;
                    metExciseInformationTable.AvailableQty  = 0.00;

                    validInsert = true;
                }
                else if (metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::TransferOrderShip &&
                 metInventTransExciseRegisterUpdateView.StatusIssue == StatusIssue::Sold)
                {
                    metExciseInformationTable.InventoryQty  = metInventTransExciseRegisterUpdateView.Qty;
                    metExciseInformationTable.AvailableQty  = 0.00;

                    validInsert = true;
                }
                else if (metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::Purch &&
                 _contract.parmTransactionType() == METTransactionType::Negative && metInventTransExciseRegisterUpdateView.Qty < 0)
                {
                    StatusIssue purchStatus = metInventTransExciseRegisterUpdateView.StatusIssue;
 
                    if (purchStatus == StatusIssue::Deducted ||  purchStatus == StatusIssue::Sold)
                    {
                        metExciseInformationTable.InventoryQty  = metInventTransExciseRegisterUpdateView.Qty;
                        metExciseInformationTable.AvailableQty  = 0.00;

                        validInsert = true;
                    }
                }
                else if (InventJournalTable::find(metInventTransExciseRegisterUpdateView.ReferenceId).Posted == NoYes::Yes)
                {
                    metExciseInformationTable.InventoryQty  = metInventTransExciseRegisterUpdateView.Qty;

                    validInsert = true;
                }
                else
                {
                    validInsert = false;
                }

                if (metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::Sales && 
                    metInventTransExciseRegisterUpdateView.Qty > 0 &&
                    SalesLine::findInventTransId(metInventTransExciseRegisterUpdateView.InventTransId).ReturnDispositionCodeId != metCustParameters.DispositionCodeRegistration)
                {
                    onlyCredit = true;
                    validInsert = false;
                }

                validPreInsert = onlyCredit ? onlyCredit : validInsert;

                validInsert = this.addingExciseInformationRecordToRecordList(metExciseInformationTable, validInsert, metExciseRegisterEntry);

                if (validPreInsert && _contract.parmCreateDutyCredit() == NoYes::Yes &&
             _contract.parmReferenceId() == metInventTransExciseRegisterUpdateView.ReferenceCategory &&
             ((_contract.parmTransactionType() == METTransactionType::Positive && metInventTransExciseRegisterUpdateView.Qty > 0) ||
             (_contract.parmTransactionType() == METTransactionType::Negative && metInventTransExciseRegisterUpdateView.Qty < 0)))
                {
                    if (metInventTransExciseRegisterUpdateView.ReferenceCategory != InventTransType::InventCounting ||
                 (metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::InventCounting &&
                 !InventCountingReasonCode::find(InventJournalTrans::findInventTransId(metExciseInformationTable.InventTransId).CountingReasonCode).METExemptFromDuty))
                    {
                        if (metInventTransExciseRegisterUpdateView.ReferenceCategory != InventTransType::InventCounting)
                        {
                            SalesLine salesLineCheck = SalesLine::findInventTransId(metInventTransExciseRegisterUpdateView.InventTransId);

                            if (salesLineCheck)
                            {
                                ReturnReasonCode    returnReasonCode;
                                SalesTable          salesTableReasonCode = salesLineCheck.salesTable(); 

                                select firstonly RecId from returnReasonCode
                                    where returnReasonCode.ReasonCodeId == salesTableReasonCode.ReturnReasonCodeId
                                    && returnReasonCode.METDispositionCodeId == salesLineCheck.ReturnDispositionCodeId
                                    && returnReasonCode.METCreateDutyCredit == NoYes::Yes;

                                if (returnReasonCode.RecId)
                                {
                                    CustTable custTable = CustTable::find(salesTableReasonCode.CustAccount);
                                    if ( custTable && !custTable.metGetCustomerBooleanAttribute(salesTableReasonCode.CustAccount, METConstants::dutyFree))
                                    {
                                        this.createDutyEditRecords(metInventTransExciseRegisterUpdateView);
                                    }
                                }
                            }
                        }
                        else
                        {
                            this.createDutyEditRecords(metInventTransExciseRegisterUpdateView);
                        }
                    }
                }
            }
     
        }
        //This method will be used to upload migrated records. 
        //If any logic change above then need to update here as well
        this.insertMigratedRecords(_contract);

        this.updateExciseInformationRecords(_contract);
    }

    /// <summary>
    /// Method to update the excise information records
    /// </summary>
    /// <param name = "_contract">Data contract reference</param>
    public void updateExciseInformationRecords(METExciseInformationTableUpdateContract     _contract)
    {
        METInventTransExciseRegisterUpdateView          metInventTransExciseRegisterUpdateView;
        boolean                                         validInsert;
        boolean                                         isReturn;
        METExciseRegisterEntry                          metExciseRegisterEntry;
        TransDateTime                                   transDateTime = DateTimeUtil::utcNow();
        boolean                                         dutyRateChanged = false;            
        METVendorClaimAmount                            metDutyRollVarianceClaimQtyOrig;
        METVendorClaimAmount                            metDutyRollVarianceClaimQtyNow;
        METExciseDutyParameteres                        exciseDutyParameteres   = METExciseDutyParameteres::find();

        while select validtimestate(transDateTime) metExciseRegisterEntry
            join metInventTransExciseRegisterUpdateView
            where metInventTransExciseRegisterUpdateView.ItemId == metExciseRegisterEntry.ItemId
            && metInventTransExciseRegisterUpdateView.ReferenceId == metExciseRegisterEntry.OrderNumber
            && (metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::Purch
            || metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::TransferOrderReceive
            || metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::TransferOrderShip)
            && metInventTransExciseRegisterUpdateView.ReferenceCategory == _contract.parmReferenceId()
            && metExciseRegisterEntry.Migrated == NoYes::No
            && metExciseRegisterEntry.IsError == NoYes::No
            join metExciseInformationTable
            where metExciseInformationTable.ExciseRegisterReferenceId == metExciseRegisterEntry.ReferenceId
            && metExciseRegisterEntry.VersionNumberRegister > metExciseInformationTable.VersionNumberRegister
        {
            METExciseInformationTable   metExciseInformationTableUpd    = METExciseInformationTable::findByRecId(metExciseInformationTable.RecId, true);
            METDutyRollVariance         metDutyRollVariance, dutyRollVarianceClaimAmt, metDutyRollVarianceAccural, newMetDutyRollVariance;

            if ((_contract.parmTransactionType() == METTransactionType::Positive && metExciseRegisterEntry.ReceiptQuantity > 0)  ||
                (_contract.parmTransactionType() == METTransactionType::Negative && metExciseRegisterEntry.ReceiptQuantity < 0))
            {
                InventTable                 inventTable;             
                METInventTable              metinventTable; 

                [inventTable, metinventTable] = this.getItemCache(metExciseInformationTable.ItemId);

                metExciseInformationTableUpd.Lodgement      = metExciseRegisterEntry.Lodgement;
                metExciseInformationTableUpd.PackingSlipId  = metExciseRegisterEntry.OriginDocumentNumber;
                metExciseInformationTableUpd.VersionNumberRegister  = metExciseRegisterEntry.VersionNumberRegister;

                select forupdate metDutyRollVariance
                    where metDutyRollVariance.Lodgement                  == metExciseInformationTable.Lodgement
                        && metDutyRollVariance.ItemId                    == metExciseInformationTable.ItemId
                        && metDutyRollVariance.OrderNumber               == metExciseInformationTable.ReferenceNumber
                        && metDutyRollVariance.ExciseRegisterReferenceId == metExciseInformationTable.ExciseRegisterReferenceId
                        && metDutyRollVariance.VersionNumberRegister             == metExciseInformationTable.VersionNumberRegister;

                if (metDutyRollVariance.DutyValue != metExciseRegisterEntry.DutyRateReceived)
                {
                    dutyRateChanged = true;

                    select sum(ClaimAmount) from dutyRollVarianceClaimAmt
                        where dutyRollVarianceClaimAmt.Lodgement                  == metExciseInformationTable.Lodgement
                            && dutyRollVarianceClaimAmt.ItemId                    == metExciseInformationTable.ItemId
                            && dutyRollVarianceClaimAmt.OrderNumber               == metExciseInformationTable.ReferenceNumber
                            && dutyRollVarianceClaimAmt.ExciseRegisterReferenceId == metExciseInformationTable.ExciseRegisterReferenceId
                            && dutyRollVarianceClaimAmt.ClaimCreated             == NoYes::Yes;

                    select sum(ClaimAmount) from metDutyRollVarianceAccural
                        where metDutyRollVarianceAccural.Lodgement                  == metExciseInformationTable.Lodgement
                            && metDutyRollVarianceAccural.ItemId                    == metExciseInformationTable.ItemId
                            && metDutyRollVarianceAccural.OrderNumber               == metExciseInformationTable.ReferenceNumber
                            && metDutyRollVarianceAccural.ExciseRegisterReferenceId == metExciseInformationTable.ExciseRegisterReferenceId;
                

                    metDutyRollVarianceClaimQtyOrig = metDutyRollVarianceAccural.ClaimAmount; //Naren
                    metDutyRollVariance.DutyValue       = metExciseRegisterEntry.DutyRateReceived;
                    MetVariance dutyRollVarianceValue   = metDutyRollVariance.AverageVFD ? (metDutyRollVariance.DutyValue - metDutyRollVariance.AverageVFD) : 0;

                    if (metDutyRollVariance.ClaimCreated)
                    {
                        metDutyRollVariance.AdditionalClaimFlag = NoYes::Yes;
                        MetVariance varianceAfterUpdate = metInventTable.ItemPack ? (dutyRollVarianceValue/metInventTable.ItemPack) : dutyRollVarianceValue;
                        metDutyRollVariance.Variance = varianceAfterUpdate - metDutyRollVariance.Variance;
                    }

                    this.calcVarianceForItem(metDutyRollVariance, exciseDutyParameteres.DutyRollVarianceThreshold);

                    metDutyRollVariance.ClaimAmount     = (metDutyRollVariance.AdValoremRate / 100) * metDutyRollVariance.VarianceAmount;
                    metDutyRollVarianceClaimQtyNow = metDutyRollVariance.ClaimAmount;
                }
                else
                {
                    dutyRateChanged = false;
                }

                metDutyRollVariance.Lodgement = metExciseInformationTableUpd.Lodgement;
                metDutyRollVariance.VersionNumberRegister = metExciseInformationTableUpd.VersionNumberRegister;

                if (metExciseInformationTableUpd.RecId && metDutyRollVariance.RecId)
                {
                    if (metExciseInformationTableUpd.validateWrite())
                    {
                        try
                        {
                            ttsbegin;
                            metExciseInformationTableUpd.update();
                            if (!dutyRateChanged)
                            {
                                metDutyRollVariance.update();
                            }
                            else
                            {
                                if (!metDutyRollVariance.ClaimCreated)
                                {
                                    metDutyRollVariance.ClaimAmount = metDutyRollVariance.ClaimAmount - dutyRollVarianceClaimAmt.ClaimAmount;
                                    metDutyRollVariance.update();
                                }
                                else
                                {
                                    buf2Buf(metDutyRollVariance, newMetDutyRollVariance);

                                    newMetDutyRollVariance.ClaimAmount = newMetDutyRollVariance.ClaimAmount - dutyRollVarianceClaimAmt.ClaimAmount;
                                    newMetDutyRollVariance.ClaimCreated = NoYes::No;

                                    newMetDutyRollVariance.insert();
                                }
                            }
                            ttscommit;
                        }
                        catch
                        {
                            if (metExciseRegisterEntry)
                            {
                                this.flagErrorInRegisterEntry(metExciseRegisterEntry);
                            }

                            Error("@MET:ExciseInfoTableValidate");
                        }
                    }
                    else
                    {
                        if (metExciseRegisterEntry)
                        {
                            this.flagErrorInRegisterEntry(metExciseRegisterEntry);
                        }
                        Error("@MET:ExciseInfoTableValidate");
                    }
                    // Accrual journal creation & automation Posting for duty roll value difference claim variance update.
                    if (metDutyRollVarianceClaimQtyOrig != metDutyRollVarianceClaimQtyNow)
                    {
                        METVendorClaimAmount accrualPostingAmt = metDutyRollVarianceClaimQtyNow - metDutyRollVarianceClaimQtyOrig;
                        newMetDutyRollVariance.reread();
                        METExciseInformationTableUpdateService::createAccrualJournal(newMetDutyRollVariance ? newMetDutyRollVariance : metDutyRollVariance, metInventTransExciseRegisterUpdateView, accrualPostingAmt);
                    }
                }
            }
        }
    }

    /// <summary>
    /// Add the Excise information records to the record list
    /// </summary>
    /// <param name = "_metExciseInformationTable"> Excise information record </param>
    /// <param name = "_validInsert"> indicates valid record or not</param>
    /// <returns> boolean </returns>
    public boolean addingExciseInformationRecordToRecordList(METExciseInformationTable _metExciseInformationTable, boolean _validInsert, METExciseRegisterEntry     _exciseRegisterEntry)
    {
        if (_validInsert)
        {
            try
            {
                if (_metExciseInformationTable.validateWrite())
                {
                    _metExciseInformationTable.insert();

                    info(strfmt("@MET:ExciseInfoSuccess", _metExciseInformationTable.ReferenceNumber, _metExciseInformationTable.InventTransType));
                    _validInsert = false;

                    return _validInsert;
                }
                else
                {
                    throw Error("@MET:ExciseInfoTableValidate");
                }
            }
            catch
            {
                if (_exciseRegisterEntry.RecId)
                {
                    this.flagErrorInRegisterEntry(_exciseRegisterEntry);
                }
            }
        }
        else
        {
            if (_exciseRegisterEntry.RecId)
            {
                this.flagErrorInRegisterEntry(_exciseRegisterEntry);
            }
        }

        return _validInsert;
    }

    /// <summary>
    ///  It maps the data to the Excise information table
    /// </summary>
    /// <param name = "_metExciseInformationTable"> Excise information record </param>
    /// <param name = "_metExciseRegisterEntry"> Excise register entry record </param>
    /// <param name = "_metInventTransExciseRegisterUpdateView"> Invent trans excise register update view record </param>
    /// <returns> boolean </returns>
    public boolean mapTransferOrderShipAndReceiveData(METExciseInformationTable _metExciseInformationTable, METExciseRegisterEntry _metExciseRegisterEntry, METInventTransExciseRegisterUpdateView _metInventTransExciseRegisterUpdateView)
    {
        InventTable inventTable = InventTable::find(_metExciseRegisterEntry.ItemId);

        metExciseInformationTable.InventoryQty = this.convertQty(_metExciseRegisterEntry.ItemId,
                                                        _metExciseRegisterEntry.ReceiptQuantity,
                                                        inventTable.purchUnitId(),
                                                        inventTable.inventUnitId());
        metExciseInformationTable.AvailableQty  = metExciseInformationTable.InventoryQty;
        
        if (_metExciseRegisterEntry.RecId != 0)
        {
            this.initialiseAdditionalDetailsForExciseInformation(_metExciseInformationTable,
                                    _metExciseRegisterEntry,
                                    _metInventTransExciseRegisterUpdateView,
                                    _metInventTransExciseRegisterUpdateView.ReferenceCategory);

            return true;
        }

        return false;
    }

    /// <summary>
    /// Run process method
    /// </summary>
    /// <param name = "_contract">Contract class reference</param>
    /// <param name = "_refId">Reference id</param>
    public void runExciseInformationTableUpdateForOrder(METExciseInformationTableUpdateContract _contract, InventTransRefId _refId = '')
    {
        SalesLine salesLine;
        InventTrans inventTrans;
        InventTransOrigin inventTransOrigin;
        boolean validInsert;
        RecordInsertList    recordInsertList = new RecordInsertList(tableNum(METExciseInformationTable), false, false, false, false, false);

        while select salesLine
                where salesLine.SalesId == _refId
                && salesLine.SalesStatus == SalesStatus::Invoiced
            join inventTransOrigin
                where inventTransOrigin.InventTransId == salesLine.InventTransId
                && inventTransOrigin.ReferenceCategory == _contract.parmReferenceId()
            join inventTrans 
                where inventTrans.InventTransOrigin == inventTransOrigin.RecId
            notexists join metExciseInformationTable
                where inventTrans.RecId == metExciseInformationTable.InventTransRefRecId
        {
            validInsert = false;

            if ((_contract.parmTransactionType() == METTransactionType::Positive && inventTrans.Qty > 0) ||
                (_contract.parmTransactionType() == METTransactionType::Negative && inventTrans.Qty < 0))
            {
                metExciseInformationTable.clear();
                metExciseInformationTable.ReferenceNumber       = _refId;
                metExciseInformationTable.InventTransType       = _contract.parmReferenceId();
                metExciseInformationTable.InventTransRefRecId   = inventTrans.RecId;
                metExciseInformationTable.ItemId                = salesLine.ItemId;
                metExciseInformationTable.SiteId                = this.getInventSiteFromInventDimId(salesLine.InventDimId);
                metExciseInformationTable.InventTransId         = inventTransOrigin.InventTransId;

                metExciseInformationTable.InventoryQty  = inventTrans.Qty;
                metExciseInformationTable.AvailableQty  = 0.00;

                if (metExciseInformationTable.validateWrite())
                {
                    recordInsertList.add(metExciseInformationTable);
                    validInsert = false;

                    info(strfmt("@MET:ExciseInfoSuccess", metExciseInformationTable.ReferenceNumber, metExciseInformationTable.InventTransType));
                }
                else
                {
                    Error("@MET:ExciseInfoTableValidate");
                }
            }
        }
        
        recordInsertList.insertDatabase();
    }

    /// <summary>
    /// Convert the qty with unit of measure. 
    /// </summary>
    /// <param name = "_itemId">Itemid reference</param>
    /// <param name = "_qty">Qty to be converted</param>
    /// <param name = "_fromUnit">From unit reference</param>
    /// <param name = "_toUnit">To unit reference</param>
    /// <returns>Inventqty reference</returns>
    public InventQty convertQty(ItemId              _itemId,
                                PurchQty            _qty, 
                                UnitOfMeasureSymbol _fromUnit, 
                                UnitOfMeasureSymbol _toUnit)
    {
        InventQty       inventqty;

        inventqty = UnitOfMeasureConverter::convert(_qty,
                            UnitOfMeasure::unitOfMeasureIdBySymbol(_fromUnit),
                            UnitOfMeasure::unitOfMeasureIdBySymbol(_toUnit),
                            NoYes::No,
                            InventTable::itemProduct(_itemId),
                            NoYes::No);

        return inventqty;
    }

    /// <summary>
    /// Insert records from data migrated. 
    /// </summary>
    /// <param name = "_contract">METExciseInformationTableUpdateContract</param>
    public void insertMigratedRecords(METExciseInformationTableUpdateContract     _contract)
    {
        METExciseRegisterEntry      metExciseRegisterEntry;
        boolean                     validInsert;
        TransDateTime               transDateTime = DateTimeUtil::utcNow();  

        while select forupdate validtimestate(transDateTime) metExciseRegisterEntry
            where metExciseRegisterEntry.RecordCopied == NoYes::No  &&
                metExciseRegisterEntry.Migrated == NoYes::Yes       &&
                metExciseRegisterEntry.OriginType == _contract.parmReferenceId()
        {
            validInsert = false;

            if ((_contract.parmTransactionType() == METTransactionType::Positive && metExciseRegisterEntry.MigratedQty > 0) ||
                (_contract.parmTransactionType() == METTransactionType::Negative && metExciseRegisterEntry.MigratedQty < 0) ||
                metExciseRegisterEntry.MigratedQty == 0)
            {
                metExciseInformationTable.clear();
                metExciseInformationTable.ReferenceNumber       = metExciseRegisterEntry.OrderNumber;
                metExciseInformationTable.InventTransType       = metExciseRegisterEntry.OriginType;
                metExciseInformationTable.ItemId                = metExciseRegisterEntry.ItemId;
                metExciseInformationTable.SiteId                = metExciseRegisterEntry.SiteId;

                metExciseInformationTable.ExciseRegisterReferenceId     = metExciseRegisterEntry.ReferenceId;

                if (metExciseRegisterEntry.OriginType == InventTransType::Purch)
                {
                    InventTable inventTable = InventTable::find(metExciseRegisterEntry.ItemId);

                    metExciseInformationTable.InventoryQty = this.convertQty(metExciseRegisterEntry.ItemId,
                                                                             metExciseRegisterEntry.MigratedQty,
                                                                            inventTable.purchUnitId(),
                                                                            inventTable.inventUnitId());

                    metExciseInformationTable.AvailableQty  = metExciseRegisterEntry.MigratedQty;

                    if (!metExciseRegisterEntry.MigratedQty)
                    {
                        metExciseInformationTable.LodgementClosed = NoYes::Yes;
                    }
                    metExciseInformationTable.Lodgement     = metExciseRegisterEntry.Lodgement;
                    metExciseInformationTable.PackingSlipId = metExciseRegisterEntry.OriginDocumentNumber;
                    validInsert = true;
                }
            
                if (validInsert)
                {
                    if (metExciseInformationTable.validateWrite())
                    {
                        try
                        {
                            ttsbegin;
                            metExciseInformationTable.insert();

                            metExciseRegisterEntry.RecordCopied = NoYes::Yes;
                            metExciseRegisterEntry.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
                            metExciseRegisterEntry.update();

                            validInsert = false;

                            info(strfmt("@MET:ExciseInfoSuccess", metExciseInformationTable.ReferenceNumber, metExciseInformationTable.InventTransType));
                            ttscommit;
                        }
                        catch
                        {
                            this.flagErrorInRegisterEntry(metExciseRegisterEntry);

                            Error("@MET:ExciseInfoTableValidate");
                        }
                    }
                    else
                    {
                        this.flagErrorInRegisterEntry(metExciseRegisterEntry);

                        Error("@MET:ExciseInfoTableValidate");
                    }
                }
            }
        }
    }

    private void initialiseAdditionalDetailsForExciseInformation(METExciseInformationTable _metExciseInformationTable,
                                                             METExciseRegisterEntry metExciseRegisterEntry,
                                                             METInventTransExciseRegisterUpdateView metInventTransExciseRegisterUpdateView,
                                                             InventTransType _inventTransType)
    {
        if (metExciseRegisterEntry.RecId)
        {
            switch(_inventTransType)
            {
                case (InventTransType::Purch) :
                case (InventTransType::TransferOrderShip):
                case (InventTransType::TransferOrderReceive):
                    {
                        _metExciseInformationTable.Lodgement     = metExciseRegisterEntry.Lodgement;
                        _metExciseInformationTable.PackingSlipId = metExciseRegisterEntry.OriginDocumentNumber;//metInventTransExciseRegisterUpdateView.PackingSlipId;

                        METExciseDutyParameteres exciseDutyParameteres = METExciseDutyParameteres::find();
                        METInventTable metInventTable = METInventTable::find(_metExciseInformationTable.ItemId);

                        dutyRollVariance.clear();
                        dutyRollVariance.Lodgement = _metExciseInformationTable.Lodgement;
                        dutyRollVariance.ItemId = _metExciseInformationTable.ItemId;
                        dutyRollVariance.Site   = _metExciseInformationTable.SiteId;
                        dutyRollVariance.ClaimQty   = _metExciseInformationTable.InventoryQty;

                    
                        METExciseSiteDutySetup  exciseSiteDutySetup;

                        select firstonly exciseSiteDutySetup
                        where exciseSiteDutySetup.ItemId == _metExciseInformationTable.ItemId
                            && exciseSiteDutySetup.SiteId == _metExciseInformationTable.SiteId;

                        METDutyRollValuesLine dutyRollValuesLine;

                        utcdatetime currentUtcDateTime = DateTimeUtil::utcNow();

                        select  firstonly validtimestate(currentUtcDateTime) AverageVFD from dutyRollValuesLine
                        where dutyRollValuesLine.Site == _metExciseInformationTable.SiteId
                            && dutyRollValuesLine.ItemId == _metExciseInformationTable.ItemId;

                        dutyRollVariance.AverageVFD = dutyRollValuesLine.AverageVFD;
                        dutyRollVariance.DutyValue = metExciseRegisterEntry.DutyRateReceived;
                        dutyRollVariance.CurrentDutyValue = exciseSiteDutySetup.ValueForDuty;

                        this.calcVarianceForItem(dutyRollVariance, exciseDutyParameteres.DutyRollVarianceThreshold);

                        METExciseInformationTable   metExciseInformationTableloc;

                        select firstonly metExciseInformationTableloc
                        group by ReferenceNumber
                        where metExciseInformationTableloc.Itemid == _metExciseInformationTable.ItemId;

                        if (!metExciseInformationTableloc)
                        {
                            dutyRollVariance.AverageVFD = 0;
                            dutyRollVariance.Variance = 0;
                        }


                        dutyRollVariance.AdValoremRate = metInventTable.metGetAdValoremRate();
                        dutyRollVariance.ClaimAmount = (dutyRollVariance.AdValoremRate / 100) * dutyRollVariance.VarianceAmount;

                        dutyRollVariance.OrderNumber = _metExciseInformationTable.ReferenceNumber;
                        dutyRollVariance.VendAccount = (select firstonly OrderAccount from PurchTable where PurchTable.PurchId == dutyRollVariance.OrderNumber).OrderAccount;
                        dutyRollVariance.InventTransType = _inventTransType;
                        dutyRollVariance.ExciseRegisterReferenceId = _metExciseInformationTable.ExciseRegisterReferenceId;
                        dutyRollVariance.VersionNumberRegister = _metExciseInformationTable.VersionNumberRegister;

                        if (dutyRollVariance.validateWrite())
                        {
                            // Accrual journal creation & automation Posting for duty roll value claim variance.
                            if (dutyRollVariance.ClaimAmount)
                            {
                                dutyRollVariance.IsAccrualPosted = METExciseInformationTableUpdateService::createAccrualJournal(dutyRollVariance, metInventTransExciseRegisterUpdateView, dutyRollVariance.ClaimAmount);
                            }

                            try
                            {
                                if (dutyRollVariance.RecId)
                                {
                                    dutyRollVariance.update();
                                }
                                else
                                {
                                    dutyRollVariance.insert();
                                }
                            }
                            catch
                            {
                                Error(strFmt("@MET:DutyInsertFailed", dutyRollVariance.OrderNumber));
                            }
                        }
                        else
                        {
                            Error(strFmt("@MET:DutyInsertFailed", dutyRollVariance.OrderNumber));
                        }
                        break;
                    }
            }
        }
    }

    /// <summary>
    /// Creates a duty credit record based on the excise register update view.
    /// </summary>
    /// <param name="_metInventTransExciseRegisterUpdateView">
    /// The excise register update view containing item ID, quantity, inventDimId, and reference ID.
    /// </param>
    /// <remarks>
    /// This method performs the following:
    /// - Retrieves site ID from the inventDim record.
    /// - Looks up duty rate from METExciseSiteDutySetup based on item and site.
    /// - Populates the duty credit table with item, site, duty rate, quantity, return quantity, and tariff code.
    /// - Retrieves the RMA number from the sales order based on the reference ID.
    /// - Validates and adds the record to the duty credit insert list if valid.
    /// </remarks>

    private void createDutyEditRecords(METInventTransExciseRegisterUpdateView _metInventTransExciseRegisterUpdateView)
    {
        Salestable                  salestable;
        InventDim                   inventDim;
        METDutyRate                 dutyRate;

        dutyCreditTable.clear();
        dutyCreditTable.SiteId = InventDim::find(_metInventTransExciseRegisterUpdateView.inventDimId).inventSiteId;
        dutyCreditTable.ItemId = _metInventTransExciseRegisterUpdateView.ItemId;

        METExciseSiteDutySetup  exciseSiteDutySetup;

        select firstonly ValueForDuty, DutyTotal, ExcisePerCase from exciseSiteDutySetup
            where exciseSiteDutySetup.ItemId == dutyCreditTable.ItemId
            && exciseSiteDutySetup.SiteId == dutyCreditTable.SiteId;

        inventDim.clear();
        inventDim.InventSiteId          = dutyCreditTable.SiteId;
        inventDim                       = InventDim::findDim(inventDim);
        
        METSalesUnit    salesUnit       = InventItemSalesSetup::find(dutyCreditTable.ItemId, inventDim.inventDimId).METSalesUnit;

        real ItempackSalesunit = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(dutyCreditTable.ItemId,
                                                                                                          inventDim.inventDimId,
                                                                                                          1,
                                                                                                          salesUnit,
                                                                                                          METConstants::unitEach,
                                                                                                          NoYes::No,
                                                                                                          NoYes::No);
       
        dutyCreditTable.CreditClosed = NoYes::No;
        dutyCreditTable.CreditRemaining = _metInventTransExciseRegisterUpdateView.Qty;
        dutyCreditTable.ReturnQuantity = _metInventTransExciseRegisterUpdateView.Qty;
        METInventTable metInventTable = METInventTable::find(_metInventTransExciseRegisterUpdateView.ItemId);
        dutyCreditTable.TariffItemCodeBaseRecid = metInventTable.METTariffItemCodeBaseRecid;

        METCustomExcise customExcise = metInventTable.customExcise();

        if (customExcise == METCustomExcise::C)
        {
            dutyRate = exciseSiteDutySetup.DutyTotal / ItempackSalesunit; // Total duty per case / sales unit per case
        }
        else
        {
            dutyRate = exciseSiteDutySetup.ExcisePerCase / ItempackSalesunit;
        }

        dutyCreditTable.DutyRate = _metInventTransExciseRegisterUpdateView.Qty * dutyRate;

        select firstonly ReturnItemNum from salestable
            where salestable.SalesId == _metInventTransExciseRegisterUpdateView.ReferenceId;

        dutyCreditTable.RMANumber = salestable.ReturnItemNum;

        if (_metInventTransExciseRegisterUpdateView.ReferenceCategory == InventTransType::InventCounting)
        {
            dutyCreditTable.RMANumber = InventJournalTrans::findInventTransId(_metInventTransExciseRegisterUpdateView.InventTransId).JournalId;
        }

        if (dutyCreditTable.validateWrite())
        {
            try
            {
                dutyCreditTable.insert();
            }
            catch
            {
                exceptionTextFallThrough();
            }
        }
    }

    /// <summary>
    /// Captures the current error message
    /// </summary>
    /// <param name = "infoLogdata"> InfologData </param>
    /// <returns> str </returns>
    public static str getErrorMsg(InfologData infoLogdata)
    {
        SysInfoLogEnumerator    sysInfologEnumerator = SysInfologEnumerator::newData(infoLogdata);
        str                     errorMsg = '';
        
        while(sysInfologEnumerator.moveNext())
        {
            if(sysInfologEnumerator.currentException())
            {
                SysInfologMessageStruct infoMessageStruct = SysInfologMessageStruct::construct(sysInfologEnumerator.currentMessage());
                errorMsg += infoMessageStruct.message();
            }
        }

        return errorMsg;
    }

    /// <summary>
    /// creates the Accrual journals
    /// </summary>
    /// <param name = "_metDutyRollVariance"> METDutyRollVariance </param>
    /// <param name = "_metInventTransExciseRegisterUpdateView"> METInventTransExciseRegisterUpdateView </param>
    /// <param name = "_accrualPostingAmt"> METVendorClaimAmount </param>
    public static boolean createAccrualJournal(METDutyRollVariance _metDutyRollVariance, METInventTransExciseRegisterUpdateView _metInventTransExciseRegisterUpdateView, METVendorClaimAmount _accrualPostingAmt)
    {
        METExciseDutyParameteres metExciseDutyParameteres = METExciseDutyParameteres::find();
        boolean ret = false;
        if(metExciseDutyParameteres.AccrualAccountNum && metExciseDutyParameteres.DutyVarianceAccountNum && metExciseDutyParameteres.JournalName)
        {
            try
            {
                ret = METDutyRollVarianceAccuralJournalPostingHelper::createAccuralJournal(metExciseDutyParameteres, _metDutyRollVariance, _metInventTransExciseRegisterUpdateView, _accrualPostingAmt);
            }
            catch
            {
                str errorMsg = METExciseInformationTableUpdateService::getErrorMsg(infolog.infologData());
            
                error(strFmt(errorMsg + "@MET:AccrualJournalPostFailedMsg",
                        _metDutyRollVariance.Lodgement, _metDutyRollVariance.ItemId, _metDutyRollVariance.OrderNumber));
            }
        }
        else
        {
            error("@MET:DutyRollVarianceParameterErrMsg");
        }

        return ret;
    }

    /// <summary>
    /// Update the flag while error in record processing
    /// </summary>
    /// <param name = "_metExciseRegisterEntry">METExciseRegisterEntry reference</param>
    public void flagErrorInRegisterEntry(METExciseRegisterEntry  _metExciseRegisterEntry)
    {
        ttsbegin;
        _metExciseRegisterEntry.reread();
        _metExciseRegisterEntry.selectForUpdate(true);
        _metExciseRegisterEntry.IsError = NoYes::Yes;
        _metExciseRegisterEntry.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
        _metExciseRegisterEntry.doUpdate();

        error(strFmt("@MET:ErrorLodgement", _metExciseRegisterEntry.OrderNumber, _metExciseRegisterEntry.Lodgement));

        ttscommit;
    }

    /// <summary>
    /// Calculate variance for item
    /// </summary>
    /// <param name = "_dutyRollVariance">METDutyRollVariance table buffer</param>
    /// <param name = "_dutyRollVarianceThreshold">METDutyRollVarianceThreshold</param>
    public void calcVarianceForItem(METDutyRollVariance _dutyRollVariance, METDutyRollVarianceThreshold _dutyRollVarianceThreshold)
    {
        InventItemSalesSetup            inventItemSalesSetup;
        InventDim                       inventDim;
		InventQty                       factor;
                    
        select firstonly METSalesUnit from inventItemSalesSetup
            join inventDim
        Where inventDim.inventDimId == inventItemSalesSetup.InventDimId
            && inventItemSalesSetup.ItemId == _dutyRollVariance.ItemId
            && inventDim.InventSiteId == _dutyRollVariance.Site;

        METPurchUnit metPurchUnit = InventItemPurchSetup::find(_dutyRollVariance.ItemId, inventDim.inventDimId).METPurchUnit;
                
        _dutyRollVariance.Variance = _dutyRollVariance.DutyValue - _dutyRollVariance.AverageVFD;

        if (metPurchUnit != inventItemSalesSetup.METSalesUnit)
        {
            factor = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_dutyRollVariance.ItemId,
                                                                                            inventDim.inventDimId,
                                                                                            1,
                                                                                            metPurchUnit,
                                                                                            inventItemSalesSetup.METSalesUnit,
                                                                                            NoYes::No,
                                                                                            NoYes::No);
            _dutyRollVariance.VarianceOuter = factor * _dutyRollVariance.Variance;
        }
        else
        {
            _dutyRollVariance.VarianceOuter = _dutyRollVariance.Variance;
        }

        factor = EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_dutyRollVariance.ItemId,
                                                                                        inventDim.inventDimId,
                                                                                        1,
                                                                                        metPurchUnit,
                                                                                        METConstants::unitEach,
                                                                                        NoYes::No,
                                                                                        NoYes::No);

        _dutyRollVariance.VarianceAmount = factor ? ((decRound(_dutyRollVariance.VarianceOuter, 2) / factor) *  decRound(_dutyRollVariance.ClaimQty, 2)) : 0;

        if (abs(_dutyRollVariance.Variance) > _dutyRollVarianceThreshold)
        {
            _dutyRollVariance.VarianceExceedsThreshold = NoYes::Yes;
        }
    }

    /// <summary>
    /// Initializes a new METDutyRollVariance table buffer.
    /// </summary>
    /// <param name = "_metExciseInformationTable"></param>
    /// <param name = "_metExciseRegisterEntry"></param>
    /// <param name = "metInventTransExciseRegisterUpdateView"></param>
    /// <param name = "_inventTransType"></param>
    /// <param name = "_metinventTable"></param>
    /// <param name = "_exciseDutyParameteres"></param>
    /// <returns></returns>
    private METDutyRollVariance initialiseMETDutyRollVariance(METExciseInformationTable _metExciseInformationTable,
                                            METExciseRegisterEntry _metExciseRegisterEntry,
                                            METInventTransExciseRegisterUpdateView _metInventTransExciseRegisterUpdateView,
                                            InventTransType _inventTransType,
                                            METInventTable _metinventTable = null,
                                            METExciseDutyParameteres _exciseDutyParameteres = null)
    {
        METDutyRollVariance dutyRollVarianceLoc;

        if (_metExciseRegisterEntry)
        {
            if (!_metinventTable)
            {
                _metinventTable = METInventTable::find(_metExciseRegisterEntry.ItemId);
            }

            if (!_exciseDutyParameteres)
            {
                _exciseDutyParameteres = METExciseDutyParameteres::find();
            }   
       
            METExciseSiteDutySetup  exciseSiteDutySetup;
            select firstonly exciseSiteDutySetup
                where exciseSiteDutySetup.ItemId  == _metExciseInformationTable.ItemId
                    && exciseSiteDutySetup.SiteId == _metExciseInformationTable.SiteId;

            METDutyRollValuesLine dutyRollValuesLine;
            utcdatetime currentUtcDateTime = DateTimeUtil::utcNow();
            select  firstonly validtimestate(currentUtcDateTime) AverageVFD from dutyRollValuesLine
                where dutyRollValuesLine.Site    == _metExciseInformationTable.SiteId
                    && dutyRollValuesLine.ItemId == _metExciseInformationTable.ItemId;
                        
            dutyRollVarianceLoc.Lodgement       = _metExciseInformationTable.Lodgement;
            dutyRollVarianceLoc.ItemId          = _metExciseInformationTable.ItemId;
            dutyRollVarianceLoc.OrderNumber     = _metExciseInformationTable.ReferenceNumber;
            dutyRollVarianceLoc.VersionNumberRegister   = _metExciseInformationTable.VersionNumberRegister;//metExciseRegisterEntry.VersionNumberRegister
            dutyRollVarianceLoc.ExciseRegisterReferenceId = _metExciseInformationTable.ExciseRegisterReferenceId;
                    
            dutyRollVarianceLoc.Site             = _metExciseInformationTable.SiteId;
            dutyRollVarianceLoc.ClaimQty         = _metExciseInformationTable.InventoryQty;

            dutyRollVarianceLoc.AverageVFD       = dutyRollValuesLine.AverageVFD;
            dutyRollVarianceLoc.DutyValue        = _metExciseRegisterEntry.DutyRateReceived;
            dutyRollVarianceLoc.CurrentDutyValue = exciseSiteDutySetup.ValueForDuty;

            this.calcVarianceForItem(dutyRollVarianceLoc, _exciseDutyParameteres.DutyRollVarianceThreshold);
                    
            dutyRollVarianceLoc.AdValoremRate   = _metinventTable.metGetAdValoremRate();
            dutyRollVarianceLoc.ClaimAmount     = (dutyRollVarianceLoc.AdValoremRate / 100) * dutyRollVarianceLoc.VarianceAmount;
            dutyRollVarianceLoc.InventTransType = _metExciseInformationTable.InventTransType;
            dutyRollVarianceLoc.VendAccount     = PurchTable::find(_metExciseInformationTable.ReferenceNumber).OrderAccount;
        }
        return dutyRollVarianceLoc;
    }
